            return random.randint(1, 1024)

        m = generate_random_size()
        n = generate_random_size()
        k = generate_random_size()

        arguments.append((m, n, k, dtype, device, rtol, atol))

    return "m, n, k, dtype, device, rtol, atol", arguments

